style.css:
@-moz-document domain("mezzoscholen.magister.net") {
/* NEON ECLIPSE BACKGROUND */
html, body, #app {
    background-color: #08060d !important;
    background-image:
        radial-gradient(circle at 10% 15%, rgba(135,35,255,.32), transparent 40%),
        radial-gradient(circle at 90% 85%, rgba(255,25,75,.25), transparent 42%) !important;
    background-attachment: fixed !important;
}

/* TRANSPARENT MAIN AREAS */
main, [role="main"], app-root {
    background: transparent !important;
}

/* GLASS TABS */
[role="tab"],
[role="tablist"] > *,
[class*="tab-item"] {
    background: rgba(255,255,255,.035) !important;
    backdrop-filter: blur(18px) saturate(160%) !important;
    border: 1px solid rgba(190,140,255,.15) !important;
    border-radius: 14px !important;
    color: #e9dcff !important;
    box-shadow: none !important;
    transition: all .3s ease !important;
}

/* TAB HOVER */
[role="tab"]:hover,
[role="tablist"] > *:hover,
[class*="tab-item"]:hover {
    background: rgba(145,65,255,.12) !important;
    border-color: rgba(190,100,255,.7) !important;
    box-shadow: 0 0 15px rgba(160,65,255,.3) !important;
}

/* ACTIVE TAB */
[role="tab"][aria-selected="true"] {
    background: rgba(140,50,220,.16) !important;
    border: 1px solid rgba(195,110,255,.8) !important;
    box-shadow: 0 0 18px rgba(160,60,255,.3) !important;
    color: white !important;
}

/* TRANSPARENT TAB BAR */
[role="tablist"] {
    background: transparent !important;
    border: none !important;
}
}
